        MapSqlParameterSource mapSqlParameterSource = new MapSqlParameterSource().addValue(ALERT_ID, alertId);

        try {
            return namedParameterJdbcTemplate.queryForObject(SQL_GET_ORIGINAL_EXPIRATION, mapSqlParameterSource, LocalDate.class);
        } catch (EmptyResultDataAccessException e){
            LOG.error("Failed to get original expiration date for alert {}. Alert does not exist", alertId, e);
            throw new MockSimsCustomException(404, String.format("Failed to get original expiration date for alert %d. Alert does not exist.", alertId));
        } catch (DataAccessException e) {
            LOG.error("Failed to get original expiration date for alert {}.", alertId, e);
            throw new MockSimsCustomException(500, "Failed to get original expiration date for alert " + alertId + ".");
        }
    }

    @Override
    public MarkdownRulesRecord getMarkdownRules(String subcommodityNumber) {
        MapSqlParameterSource mapSqlParameterSource = new MapSqlParameterSource().addValue(SUBCOMMDITY_NUMBER, subcommodityNumber);

        try {
            return namedParameterJdbcTemplate.queryForObject(SQL_GET_MARKDOWN_RULES_INFO, mapSqlParameterSource, new MarkdownRulesRecordMapper());
        } catch (DataAccessException e){
            LOG.error("Failed to get markdown rules information for subcommodity {}.", subcommodityNumber, e);
            throw new MockSimsCustomException(500, "Failed to get markdown rules information for subcommodity " + subcommodityNumber + ".");
        }
    }

    @Override
    public void insertNewAlert(LocalDate newExpirationDate, LocalDate newRfiDate, LocalDate newMarkdownDate, Integer alertId) {
        MapSqlParameterSource mapSqlParameterSource = new MapSqlParameterSource()
                .addValue(NEW_EXPIRATION_DATE, newExpirationDate)
                .addValue(NEW_RFI_DATE, newRfiDate)
                .addValue(NEW_MD_DATE, newMarkdownDate)
                .addValue(ALERT_ID, alertId);

        try {
            namedParameterJdbcTemplate.update(SQL_CREATE_NEW_ALERT, mapSqlParameterSource);
        } catch (DataAccessException e){
            LOG.error("Failed to create new updated alert for alert {}.", alertId, e);
            throw new MockSimsCustomException(500, "Failed to create new update alert for alert " + alertId + ".");
        }

    }

    @Override
    public void deactivateOldAlert(Integer alertId) {
        MapSqlParameterSource mapSqlParameterSource = new MapSqlParameterSource().addValue(ALERT_ID, alertId);
        int numRowsUpdated;
        try {
            numRowsUpdated = namedParameterJdbcTemplate.update(SQL_DEACTIVATE_PDM_ALERT, mapSqlParameterSource);
        } catch(DataAccessException e){
            LOG.error("Failed to deactivate alert {}.", alertId, e);
            throw new MockSimsCustomException(500, "Failed to deactivate alert " + alertId + ".");
        }

        if(numRowsUpdated != 1){
            throw new MockSimsCustomException(500, "Failed to deactivate alert " + alertId + ". More or less than one row was updated");
        }

    }


    @Override
    public void updatePdmAlert(Integer alertId, LocalDateTime actionedTime, String userEuid) {
        MapSqlParameterSource mapSqlParameterSource = new MapSqlParameterSource()
                .addValue(ALERT_ID, alertId)
                .addValue(ACTIONED_TIME, actionedTime)
                .addValue(IS_ACTIVE, false)
                .addValue(USER_EUID, userEuid)
                .addValue(ACTION_CODE, "PB");

        int numRowsUpdated;

        try {
            numRowsUpdated = namedParameterJdbcTemplate.update(SQL_UPDATE_ALERT_ACTION_INFO, mapSqlParameterSource);
        } catch (DataAccessException e){
            LOG.error("Failed to update PDM Alert.", e);
            throw new MockSimsCustomException(500, "Failed to update PDM alert.");
        }

        if(numRowsUpdated != 1){
            LOG.error("Failed to update PDM Alert ID = {}. Did not update exactly row.", alertId);
            throw new MockSimsCustomException(500, "Failed to update PDM alert.");
        }
    }

    @Override
    public void deactivateActiveDuplicateAlerts(String storeNumber, String divisionNumber, String upcNumber, LocalDateTime actionedTime, String userEuid) {
        MapSqlParameterSource params = new MapSqlParameterSource()
                .addValue(STORE_NUMBER, storeNumber)
                .addValue(DIVISION_NUMBER, divisionNumber)
                .addValue(UPC_NUMBER, upcNumber)
                .addValue(ACTIONED_TIME, actionedTime)
                .addValue(USER_EUID, userEuid)
                .addValue(ACTION_CODE, "DP");

        try {
            namedParameterJdbcTemplate.update(SQL_DEACTIVATE_ACTIVE_DUE_DUPLICATE_ALERTS_FOR_UPC, params);
        } catch (DataAccessException error) {
            LOG.error("Failed to deactivate active duplicate PDM alerts for upc {} store {} division {}.", upcNumber, storeNumber, divisionNumber, error);

            throw new MockSimsCustomException(500, "Failed to deactivate duplicate active PDM alerts.");
        }
    }
}

package mocksims.project.backend.service;

import mocksims.project.backend.api.domain.MarkdownRulesRecord;
import mocksims.project.backend.api.domain.PushBackExpirationRequest;
import mocksims.project.backend.controller.ProductsController;
import mocksims.project.backend.exception.MockSimsCustomException;
import mocksims.project.backend.repository.PushBackExpirationRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.time.LocalDateTime;

@Service
public class PushBackExpirationServiceImpl implements PushBackExpirationService {

    private static final Logger LOG = LoggerFactory.getLogger(PushBackExpirationServiceImpl.class);

    private final PushBackExpirationRepository pushBackExpirationRepository;

    public PushBackExpirationServiceImpl (PushBackExpirationRepository pushBackExpirationRepository){
        this.pushBackExpirationRepository = pushBackExpirationRepository;
    }

    @Override
    @Transactional
    public void pushBackExpirationDate(PushBackExpirationRequest pushBackExpirationRequest) {
        /*
        get subcommodity numbers from the alertid
        get new markdown rules from the subcommodity number
        set dates based on the new day
        insert new row into the table
        deactivate the old row
         */

        boolean isActive = pushBackExpirationRepository.getAlertActiveStatus(pushBackExpirationRequest.getAlertId());

        if(!isActive){
            throw new MockSimsCustomException(400, String.format("Failed to push back expiration date for alert %d. An inactive alert cannot be pushed back.", pushBackExpirationRequest.getAlertId()));
        }

        LocalDate originalExpiration = pushBackExpirationRepository.getOriginalExpirationDate(pushBackExpirationRequest.getAlertId());

        if(originalExpiration.isAfter(pushBackExpirationRequest.getNewExpirationDate()) || originalExpiration.isEqual(pushBackExpirationRequest.getNewExpirationDate())){
            throw new MockSimsCustomException(400, String.format("Failed to push back expiration for alert %d. New expiration date must be after original expiration date.", pushBackExpirationRequest.getAlertId()));
        }

        String subcommodityNumber = pushBackExpirationRepository.getSubcommodityNumber(pushBackExpirationRequest.getAlertId());
        MarkdownRulesRecord markdownRulesRecord = pushBackExpirationRepository.getMarkdownRules(subcommodityNumber);
        LocalDate newMdDate = pushBackExpirationRequest.getNewExpirationDate().minusDays(markdownRulesRecord.getDaysBeforeExpToMd());
        LocalDate newRfiDate = pushBackExpirationRequest.getNewExpirationDate().minusDays(markdownRulesRecord.getDaysBeforeExpToRfi());

        LocalDateTime currentTime = LocalDateTime.now();

        pushBackExpirationRepository.insertNewAlert(pushBackExpirationRequest.getNewExpirationDate(), newRfiDate, newMdDate, pushBackExpirationRequest.getAlertId());

        pushBackExpirationRepository.updatePdmAlert(pushBackExpirationRequest.getAlertId(), currentTime, pushBackExpirationRequest.getUserEuid());

        pushBackExpirationRepository.deactivateActiveDueDuplicateAlertsForAlertId(pushBackExpirationRequest.getAlertId(), currentTime, pushBackExpirationRequest.getUserEuid());

    }
}

